            p.[Depth] + 1 AS [Depth]
        FROM
            [${flyway:defaultSchema}].[TaxJurisdiction] c
        INNER JOIN
            CTE_RootParent p ON c.[ID] = p.[ParentTaxJurisdictionID]
        WHERE
            p.[Depth] < 100
    )
    SELECT TOP 1
        [RootParentID] AS RootID
    FROM
        CTE_RootParent
    WHERE
        [ParentTaxJurisdictionID] IS NULL
    ORDER BY
        [RootParentID]
);
