        [ParentTaxJurisdictionID] = CASE WHEN @ParentTaxJurisdictionID_Clear = 1 THEN NULL ELSE ISNULL(@ParentTaxJurisdictionID, [ParentTaxJurisdictionID]) END,
        [IsActive] = ISNULL(@IsActive, [IsActive])
